-- Store schema and demo catalog for an existing PortafolioCI database.
-- Import this file after club_de_futbol.sql using phpMyAdmin.
ALTER TABLE `ingresos` MODIFY `concepto` VARCHAR(30) NOT NULL;

CREATE TABLE IF NOT EXISTS `souvenirs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `producto` varchar(100) NOT NULL,
  `talla` enum('S','M','L','XL','XXL') DEFAULT NULL,
  `precio` decimal(10,0) NOT NULL,
  `genero` enum('Hombre','Mujer') DEFAULT NULL,
  `detalle` text DEFAULT NULL,
  `foto` longblob DEFAULT NULL,
  `stock` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `venta_souvenirs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `monto_compra` decimal(10,0) NOT NULL,
  `articulos_vendidos` text NOT NULL,
  `nombre_comprador` varchar(100) NOT NULL,
  `telefono_comprador` int(11) NOT NULL,
  `direccion_envio` varchar(100) DEFAULT NULL,
  `fecha_compra` datetime NOT NULL,
  `metodo` enum('despacho','retiro') NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `venta_entradas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `monto` int(11) NOT NULL,
  `nombre_comprador` varchar(100) NOT NULL,
  `rut_comprador` varchar(100) NOT NULL,
  `id_partido_fk` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `venta_entradas_partido_fk` (`id_partido_fk`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
